static void Main(string[] args)
{
    int[] nums = { 1, -2, 3, 0, -4, 5 };
    var posNums = from n in nums
                  where n >= 0
                  select n;

    foreach (int i in posNums) Console.Write(i + " ");
}

static void Main(string[] args)
{
    int[] nums = { 1, -2, 3, 0, -4, 5 };
    var evens = from n in nums
                where n % 2 == 0
                select n;

    foreach (int i in evens) Console.Write(i + " ");
}

static void Main(string[] args)
{
    int[] nums = { 1, -2, 3, 0, -4, 5 };
    var result = from n in nums
                 where n > -5 && n < 6
                 orderby n descending
                 select n;

    foreach (int i in result) Console.Write(i + " ");
}

static void Main(string[] args)
{
    int[] nums = { 16, 9, 25 };
    var roots = from n in nums
                where n > 0
                select Math.Sqrt(n);

    foreach (var r in roots) Console.Write(r + " ");
}

